const docId = $('Create Google Doc').first().json.documentId;
const docBody = $json.body;
const tables = $('Prepare Document').first().json.tables || [];

if (!tables.length || !docBody || !docBody.content) {
  return [{ json: { docId, requests: [], hasTables: false } }];
}

const placeholders = [];
for (const elem of docBody.content) {
  if (elem.paragraph && elem.paragraph.elements) {
    for (const el of elem.paragraph.elements) {
      if (el.textRun && el.textRun.content) {
        const text = el.textRun.content;
        const regex = /\{\{TBL:(\d+)\}\}/g;
        let match;
        while ((match = regex.exec(text)) !== null) {
          const tableIdx = parseInt(match[1]);
          placeholders.push({
            tableIdx,
            paraStartIndex: elem.startIndex,
            paraEndIndex: elem.endIndex
          });
        }
      }
    }
  }
}

if (!placeholders.length) {
  return [{ json: { docId, requests: [], hasTables: false } }];
}

placeholders.sort((a, b) => b.paraStartIndex - a.paraStartIndex);

const requests = [];
for (const ph of placeholders) {
  const table = tables.find(t => t.index === ph.tableIdx);
  if (!table) continue;
  const totalRows = 1 + table.rows.length;
  const totalCols = table.headers.length;
  if (totalCols === 0) continue;

  requests.push({
    deleteContentRange: {
      range: { startIndex: ph.paraStartIndex, endIndex: ph.paraEndIndex }
    }
  });
  requests.push({
    insertTable: {
      rows: totalRows,
      columns: totalCols,
      location: { index: ph.paraStartIndex }
    }
  });
}

return [{ json: { docId, requests, hasTables: true } }];

const docId = $('Create Google Doc').first().json.documentId;
const docBody = $json.body;

if (!docBody || !docBody.content) {
  return [{ json: { docId, requests: [] } }];
}

const requests = [];

const colors = {
  navy: { red: 0.1, green: 0.15, blue: 0.3 },
  white: { red: 1.0, green: 1.0, blue: 1.0 },
  lightGray: { red: 0.95, green: 0.96, blue: 0.97 },
  bodyText: { red: 0.15, green: 0.15, blue: 0.15 },
  borderColor: { red: 0.8, green: 0.82, blue: 0.85 }
};

const borderStyle = {
  width: { magnitude: 0.5, unit: 'PT' },
  color: { color: { rgbColor: colors.borderColor } },
  dashStyle: 'SOLID'
};

for (const elem of docBody.content) {
  if (!elem.table) continue;

  const table = elem.table;
  const tableStartIndex = elem.startIndex;
  const numRows = table.tableRows.length;
  const numCols = table.tableRows[0]?.tableCells?.length || 0;

  for (let r = 0; r < numRows; r++) {
    const row = table.tableRows[r];
    if (!row || !row.tableCells) continue;

    for (let c = 0; c < row.tableCells.length; c++) {
      const cell = row.tableCells[c];
      if (!cell) continue;

      const isHeader = (r === 0);
      const isEvenRow = (r % 2 === 0);
      const bgColor = isHeader ? colors.navy : (isEvenRow ? colors.lightGray : colors.white);

      // tableRange only (NOT tableStartLocation - they are oneof)
      requests.push({
        updateTableCellStyle: {
          tableRange: {
            tableCellLocation: {
              tableStartLocation: { index: tableStartIndex },
              rowIndex: r,
              columnIndex: c
            },
            rowSpan: 1,
            columnSpan: 1
          },
          tableCellStyle: {
            backgroundColor: { color: { rgbColor: bgColor } },
            paddingTop: { magnitude: 4, unit: 'PT' },
            paddingBottom: { magnitude: 4, unit: 'PT' },
            paddingLeft: { magnitude: 6, unit: 'PT' },
            paddingRight: { magnitude: 6, unit: 'PT' },
            borderTop: borderStyle,
            borderBottom: borderStyle,
            borderLeft: borderStyle,
            borderRight: borderStyle
          },
          fields: 'backgroundColor,paddingTop,paddingBottom,paddingLeft,paddingRight,borderTop,borderBottom,borderLeft,borderRight'
        }
      });

      // Text formatting
      if (cell.content) {
        for (const cellElem of cell.content) {
          if (cellElem.paragraph && cellElem.paragraph.elements) {
            for (const textEl of cellElem.paragraph.elements) {
              if (textEl.textRun && textEl.startIndex !== undefined) {
                const textStart = textEl.startIndex;
                const textEnd = textEl.endIndex;
                if (textStart < textEnd) {
                  requests.push({
                    updateTextStyle: {
                      range: { startIndex: textStart, endIndex: textEnd },
                      textStyle: {
                        bold: isHeader,
                        fontSize: { magnitude: isHeader ? 10 : 9.5, unit: 'PT' },
                        foregroundColor: {
                          color: { rgbColor: isHeader ? colors.white : colors.bodyText }
                        },
                        weightedFontFamily: {
                          fontFamily: isHeader ? 'Montserrat' : 'Open Sans',
                          weight: isHeader ? 600 : 400
                        }
                      },
                      fields: 'bold,fontSize,foregroundColor,weightedFontFamily'
                    }
                  });
                  requests.push({
                    updateParagraphStyle: {
                      range: { startIndex: textStart, endIndex: textEnd },
                      paragraphStyle: {
                        alignment: 'START',
                        lineSpacing: 115,
                        spaceAbove: { magnitude: 0, unit: 'PT' },
                        spaceBelow: { magnitude: 0, unit: 'PT' }
                      },
                      fields: 'alignment,lineSpacing,spaceAbove,spaceBelow'
                    }
                  });
                }
              }
            }
          }
        }
      }
    }
  }
}

return [{ json: { docId, requests } }];

const docId = $('Create Google Doc').first().json.documentId;
const docBody = $json.body;
const tables = $('Prepare Document').first().json.tables || [];

if (!tables.length || !docBody || !docBody.content) {
  return [{ json: { docId, requests: [] } }];
}

// Find all tables in document body (in order)
const docTables = [];
for (const elem of docBody.content) {
  if (elem.table) {
    docTables.push(elem.table);
  }
}

if (!docTables.length) {
  return [{ json: { docId, requests: [] } }];
}

const requests = [];

// Process tables from LAST to FIRST to avoid index shifts between tables
for (let t = Math.min(docTables.length, tables.length) - 1; t >= 0; t--) {
  const docTable = docTables[t];
  const tableData = tables[t];
  const numRows = docTable.tableRows.length;
  const numCols = docTable.tableRows[0]?.tableCells?.length || 0;

  const cellTexts = [];
  // Header row (row 0)
  for (let c = 0; c < Math.min(numCols, tableData.headers.length); c++) {
    cellTexts.push({ r: 0, c, text: String(tableData.headers[c] || '') });
  }
  // Data rows
  for (let r = 0; r < tableData.rows.length; r++) {
    for (let c = 0; c < Math.min(numCols, (tableData.rows[r] || []).length); c++) {
      cellTexts.push({ r: r + 1, c, text: String(tableData.rows[r][c] ?? '') });
    }
  }

  // Sort cells from last to first (higher row/col first)
  // This way insertText at higher index doesn't shift lower indices
  cellTexts.sort((a, b) => a.r !== b.r ? b.r - a.r : b.c - a.c);

  for (const cell of cellTexts) {
    if (cell.text && cell.r < numRows && cell.c < numCols) {
      const row = docTable.tableRows[cell.r];
      if (!row || !row.tableCells) continue;
      const cellElem = row.tableCells[cell.c];
      if (!cellElem || !cellElem.content) continue;
      // Use ACTUAL paragraph startIndex from document structure
      const para = cellElem.content[0];
      if (para && para.paragraph) {
        requests.push({
          insertText: {
            location: { index: para.startIndex },
            text: cell.text
          }
        });
      }
    }
  }
}

return [{ json: { docId, requests } }];

